CREATE TABLE public.suppliers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), name text NOT NULL, country text NOT NULL, category text NOT NULL, delivery numeric NOT NULL DEFAULT 90, quality numeric NOT NULL DEFAULT 95, reliability numeric NOT NULL DEFAULT 90, cost numeric NOT NULL DEFAULT 10000, disruptions integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.suppliers TO authenticated; GRANT ALL ON public.suppliers TO service_role; ALTER TABLE public.suppliers ENABLE ROW LEVEL SECURITY; CREATE POLICY own_suppliers ON public.suppliers FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());